from pathlib import Path
import json,hashlib
from html import escape as E

def build(root):
 D=root/'dist'; data=json.loads((root/'research/session_catalogue.json').read_text())
 def shell(route,title,body):
  base=(D/'index.html').read_text();head=base.split('<main id="main"')[0];foot=base.split('</main>',1)[1]
  import re
  head=re.sub(r'<title>.*?</title>',f'<title>{E(title)} · MQM</title>',head)
