  head=re.sub(r'<meta property="og:(title|description)" content="[^"]*">','',head)
  head=head.replace(' aria-current="page"','').replace(f'href="{route}"',f'href="{route}" aria-current="page"',1)
  dest=D/route.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
  dest.write_text(head+'<main id="main" class="wrap">'+body+'</main>'+foot)
